package br.com.cineo;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;import static br.com.cineo.MainActivity.*;
/** Assignment-based moderation with private notes and an immutable decision history. */
class ModerationDesk {
 final MainActivity a;String caseId="";ModerationDesk(MainActivity activity){a=activity;}
 void get(String p,MainActivity.Done d){a.call("GET","/v8/desk"+p,null,d);}void post(String p,JSONObject b,MainActivity.Done d){a.call("POST","/v8/desk"+p,b,d);}void page(String id,String title,String sub){a.page(id,title,sub,3,()->home());}
 String label(String kind){switch(kind){case "show":return "Produção";case "episode":return "Capítulo";case "report":return "Denúncia";case "ticket":return "Atendimento";case "proposal":return "Revisão";default:return "Recurso";}}
 void home(){a.page("admin","Central da equipe","O que precisa de atenção hoje.",3,()->a.profile());get("/home",r->{JSONObject counts=r.getJSONObject("counts");a.title(a.body,r.optInt("total")==0?"Tudo em dia":r.optInt("total")+" caso(s) aguardando",23);String role=r.optString("staff");if(!role.equals("support")){a.menu("film","Produções e capítulos",counts.optInt("show")+" produções · "+counts.optInt("episode")+" capítulos",()->cases("show","open"));a.menu("chat","Revisões e recursos",counts.optInt("proposal")+" revisões · "+counts.optInt("appeal")+" recursos",()->cases("proposal","open"));a.menu("shield","Denúncias",counts.optInt("report")+" abertas",()->cases("report","open"));}if(role.equals("admin")||role.equals("support"))a.menu("headset","Atendimento",counts.optInt("ticket")+" aguardando",()->cases("ticket","open"));if(role.equals("admin")){a.menu("team","Equipe e modelos","Responsáveis e motivos de análise",()->teamMenu());a.menu("gear","Operações","Comunicados, pesquisas, backups e versões",()->a.operations.home());}a.button(a.body,"Histórico de casos encerrados",CARD,()->cases("","resolved"));});}
 void cases(String kind,String status){page("case-list","Casos da equipe",status.equals("resolved")?"Histórico de decisões":"Ordenados por prioridade e antiguidade");LinearLayout filters=a.row();String[] values={"show","episode","proposal","appeal","report","ticket"};String[] labels={"Produções","Capítulos","Revisões","Recursos","Denúncias","Suporte"};Spinner type=a.select(filters,"TIPO",labels,kind.isEmpty()?"Produções":labels[Math.max(0,Arrays.asList(values).indexOf(kind))]);a.body.addView(filters);a.button(a.body,"Filtrar casos",CARD,()->cases(values[type.getSelectedItemPosition()],status));get("/cases?status="+status+(kind.isEmpty()?"":"&kind="+kind),r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"shield","Nenhum caso nesta área","As pendências atribuídas à equipe aparecerão aqui.");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);a.title(a.body,label(row.optString("kind"))+" · "+row.optString("target_id"),17);a.text(a.body,"Prioridade "+row.optInt("priority")+" · "+a.pro.date(row.optString("created_at")),12,MUTED);a.button(a.body,"Abrir caso",CARD,()->detail(row.optString("id")));}});}
 void detail(String id){caseId=id;page("case-detail","Analisar caso","");get("/case/"+id,r->{JSONObject c=r.getJSONObject("case"),target=r.optJSONObject("target"),show=r.optJSONObject("show");a.title(a.body,label(c.optString("kind")),23);if(show!=null){a.title(a.body,show.optString("title"),20);a.text(a.body,show.optString("synopsis"),14,MUTED);}if(target==null)a.text(a.body,"O conteúdo deste caso não está mais disponível.",14,AMBER);else if(c.optString("kind").equals("ticket")){a.title(a.body,target.optString("subject"),18);a.text(a.body,target.optString("message"),15,WHITE);}else if(c.optString("kind").equals("appeal"))a.text(a.body,target.optString("message"),15,WHITE);else if(c.optString("kind").equals("report"))a.text(a.body,"Motivo: "+target.optString("reason")+"\nTipo: "+target.optString("kind")+" · #"+target.optString("target_id"),15,WHITE);
 if(target!=null&&c.optString("kind").equals("proposal")){JSONObject content=target.getJSONObject("content"),before=content.getJSONObject("base"),patch=content.getJSONObject("patch");a.title(a.body,"Comparar versões",20);for(Iterator<String> keys=patch.keys();keys.hasNext();){String key=keys.next();a.text(a.body,key+"\nPublicada: "+before.optString(key)+"\nProposta: "+patch.optString(key),14,MUTED);}}
 JSONArray eps=r.optJSONArray("episodes");if(show!=null&&eps!=null&&eps.length()>0)a.button(a.body,"Assistir para avaliar",RED,()->a.safe(()->{JSONObject preview=new JSONObject(show.toString()).put("status","preview");a.play(preview,eps,0,"moderation");}));if(c.optString("status").equals("open")){a.button(a.body,"Registrar decisão",RED,()->decision(c));if(a.role.equals("admin"))a.button(a.body,"Atribuir e priorizar",CARD,()->assign(c));a.button(a.body,"Adicionar nota interna",CARD,()->{EditText note=new EditText(a);note.setHint("Somente a equipe responsável poderá ler");new AlertDialog.Builder(a).setTitle("Nota interna").setView(note).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,n)->a.safe(()->post("/case/"+id+"/note",a.obj("body",note.getText().toString()),ok->detail(id)))).show();});}JSONArray notes=r.getJSONArray("notes");if(notes.length()>0)a.title(a.body,"Notas internas",19);for(int i=0;i<notes.length();i++){JSONObject note=notes.getJSONObject(i);a.text(a.body,note.optString("body")+"\n"+a.pro.date(note.optString("created_at")),13,MUTED);}JSONArray history=r.getJSONArray("history");if(history.length()>0)a.title(a.body,"Histórico do caso",19);for(int i=0;i<history.length();i++){JSONObject event=history.getJSONObject(i);a.text(a.body,event.optString("action")+" · "+a.pro.date(event.optString("created_at"))+"\n"+event.optJSONObject("details").optString("note"),13,MUTED);}});}
 void decision(JSONObject c){get("/templates",r->{JSONArray templates=r.getJSONArray("items");LinearLayout form=a.col();form.setPadding(a.dp(18),a.dp(10),a.dp(18),0);String kind=c.optString("kind");String[] labels=kind.equals("report")?new String[]{"Ocultar conteúdo","Restaurar conteúdo","Descartar denúncia"}:Arrays.asList("ticket","appeal").contains(kind)?new String[]{"Responder e encerrar"}:new String[]{"Aprovar","Reprovar e solicitar ajustes"};Spinner action=a.select(form,"DECISÃO",labels,labels[0]);String[] names=new String[templates.length()+1];names[0]="Sem modelo";for(int i=0;i<templates.length();i++)names[i+1]=templates.optJSONObject(i).optString("label");Spinner template=a.select(form,"MOTIVO PADRONIZADO",names,names[0]);EditText note=a.field(form,"EXPLICAÇÃO","Detalhe a decisão ou escreva a resposta",false);note.setSingleLine(false);note.setMinLines(4);ScrollView scroll=new ScrollView(a);scroll.addView(form);new AlertDialog.Builder(a).setTitle("Concluir análise").setView(scroll).setNegativeButton("Cancelar",null).setPositiveButton("Confirmar decisão",(d,n)->a.safe(()->{String value=kind.equals("report")?new String[]{"resolved","restore","dismissed"}[action.getSelectedItemPosition()]:Arrays.asList("ticket","appeal").contains(kind)?"resolved":action.getSelectedItemPosition()==0?"approved":"rejected";JSONObject payload=a.obj("decision",value,"note",note.getText().toString());if(template.getSelectedItemPosition()>0)payload.put("template",templates.getJSONObject(template.getSelectedItemPosition()-1).getString("code"));post("/case/"+c.getString("id")+"/decide",payload,ok->detail(c.optString("id")));})).show();});}
 void assign(JSONObject c){get("/staff",r->{JSONArray members=r.getJSONArray("items");ArrayList<String> ids=new ArrayList<>(),names=new ArrayList<>();ids.add("");names.add("Sem responsável");ids.add(a.uid);names.add("Eu, administrador");for(int i=0;i<members.length();i++){JSONObject m=members.getJSONObject(i);if(c.optString("kind").equals("ticket")?!m.optString("role").equals("support"):!m.optString("role").equals("reviewer"))continue;ids.add(m.optString("user_id"));names.add(m.optString("name"));}LinearLayout form=a.col();form.setPadding(a.dp(18),a.dp(10),a.dp(18),0);Spinner person=a.select(form,"RESPONSÁVEL",names.toArray(new String[0]),names.get(0)),priority=a.select(form,"PRIORIDADE",new String[]{"0 · Normal","1","2","3","4","5 · Urgente"},"0 · Normal");new AlertDialog.Builder(a).setTitle("Distribuir caso").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,n)->a.safe(()->post("/case/"+c.optString("id")+"/assign",a.obj("assignee",ids.get(person.getSelectedItemPosition()).isEmpty()?JSONObject.NULL:ids.get(person.getSelectedItemPosition()),"priority",priority.getSelectedItemPosition()),ok->detail(c.optString("id"))))).show();});}
 void teamMenu(){page("team-management","Equipe e modelos","");a.menu("team","Colaboradores da plataforma","Análise e suporte com permissões diferentes",()->staff());a.menu("chat","Modelos de decisão","Motivos claros e consistentes",()->templates());}
 void staff(){page("staff-management","Equipe da plataforma","");get("/staff",r->{JSONArray rows=r.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject member=rows.getJSONObject(i);a.title(a.body,member.optString("name"),18);a.text(a.body,member.optString("role").equals("support")?"Atendimento":"Análise de conteúdo",13,MUTED);a.button(a.body,"Remover acesso da equipe",CARD,()->new AlertDialog.Builder(a).setTitle("Remover esta permissão?").setNegativeButton("Cancelar",null).setPositiveButton("Remover",(d,n)->a.safe(()->post("/staff",a.obj("user_id",member.optString("user_id"),"remove",true),ok->staff()))).show());}a.button(a.body,"Adicionar colaborador",RED,()->{LinearLayout form=a.col();form.setPadding(a.dp(18),a.dp(10),a.dp(18),0);EditText name=a.field(form,"NOME","Nome na equipe",false),code=a.field(form,"CÓDIGO DA CONTA","Peça o código de colaboração",false);Spinner role=a.select(form,"FUNÇÃO",new String[]{"Análise de conteúdo","Atendimento"},"Análise de conteúdo");new AlertDialog.Builder(a).setTitle("Adicionar à equipe").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Adicionar",(d,n)->a.safe(()->post("/staff",a.obj("name",name.getText().toString(),"user_id",code.getText().toString().trim(),"role",role.getSelectedItemPosition()==0?"reviewer":"support"),ok->staff()))).show();});});}
 void templates(){page("decision-templates","Modelos de decisão","");get("/templates",r->{JSONArray rows=r.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject t=rows.getJSONObject(i);a.title(a.body,t.optString("label"),18);a.text(a.body,t.optString("body"),14,MUTED);a.button(a.body,"Editar modelo",CARD,()->templateEditor(t));}a.button(a.body,"Criar modelo",RED,()->templateEditor(new JSONObject()));});}
 void templateEditor(JSONObject t){page("decision-template-editor","Modelo de decisão","");EditText code=a.field(a.body,"CÓDIGO","Ex.: imagem",false),label=a.field(a.body,"NOME","Nome do motivo",false),body=a.field(a.body,"EXPLICAÇÃO","Orientação para o criador",false);code.setText(t.optString("code"));code.setEnabled(t.optString("code").isEmpty());label.setText(t.optString("label"));body.setText(t.optString("body"));body.setSingleLine(false);body.setMinLines(5);a.button(a.body,"Salvar modelo",RED,()->a.safe(()->post("/templates",a.obj("code",code.getText().toString(),"label",label.getText().toString(),"body",body.getText().toString()),r->templates())));}
}
